spec.expr:
sum by (testName, runId) (
  jmeter_active_threads{
    job="jmeter",
    testName=~"${testName:regex}",
    runId=~"${runId:regex}"
  }
)

sum by (requestName) (
  rate(
    jmeter_requests{
      job="jmeter",
      testName=~"${testName:regex}",
      runId=~"${runId:regex}",
      isTransaction="false"
    }[1m]
  )
)

sum by (requestName) (
  rate(
    jmeter_requests{
      job="jmeter",
      testName=~"${testName:regex}",
      runId=~"${runId:regex}",
      isTransaction="false",
      requestStatus="FAIL"
    }[1m]
  )
)
or on (requestName)
(
  0 *
  sum by (requestName) (
    rate(
      jmeter_requests{
        job="jmeter",
        testName=~"${testName:regex}",
        runId=~"${runId:regex}",
        isTransaction="false"
      }[1m]
    )
  )
)

histogram_quantile(
  0.95,
  sum by (le, requestName) (
    rate(
      jmeter_response_time_histogram_bucket{
        job="jmeter",
        testName=~"${testName:regex}",
        runId=~"${runId:regex}",
        isTransaction="false"
      }[1m]
    )
  )
)

sum by (container_label_com_docker_compose_service) (
  rate(
    container_cpu_usage_seconds_total{
      job="cadvisor",
      container_label_com_docker_compose_project="mini-bank",
      container_label_com_docker_compose_service=~"app|db",
      cpu="total"
    }[1m]
  )
)

100 *
sum by (container_label_com_docker_compose_service) (
  rate(
    container_cpu_cfs_throttled_periods_total{
      job="cadvisor",
      container_label_com_docker_compose_project="mini-bank",
      container_label_com_docker_compose_service=~"app|db"
    }[1m]
  )
)
/
sum by (container_label_com_docker_compose_service) (
  rate(
    container_cpu_cfs_periods_total{
      job="cadvisor",
      container_label_com_docker_compose_project="mini-bank",
      container_label_com_docker_compose_service=~"app|db"
    }[1m]
  )
)
